INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62513700', 62513700, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR LABORATORIUM KESEHATAN LINGKUNGAN', 'Belanja Jasa Lainnya Pemeriksaan sampel lingkungan', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Tengah, Salatiga (Kota)', 16500000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Pemeriksaan sampel lingkungan ( 1, pkt, @ 16500000 );', '1. Ruang Lingkup Pekerjaan Pekerjaan ini meliputi jasa pemeriksaan, pengujian, dan analisis sampel lingkungan dalam rangka pemeliharaan sarana kantor guna memastikan kondisi lingkungan kerja yang sehat, aman, dan sesuai dengan ketentuan peraturan perundang-undangan yang berlaku. 2. Jenis Pemeriksaan Sampel Lingkungan Pemeriksaan sampel lingkungan meliputi, namun tidak terbatas pada: a. Sampel air bersih dan/atau air minum b. Sampel air limbah (jika ada) c. Sampel udara dalam ruang (indoor air quality) d. Sampel debu atau partikel lingkungan kerja e. Sampel kebisingan lingkungan kerja (opsional, sesuai kebutuhan) 3. Metode dan Pelaksanaan a. Pengambilan sampel dilakukan oleh tenaga yang kompeten dan berpengalaman b. Metode pengambilan dan pengujian sampel mengacu pada standar dan prosedur yang berlaku (SNI/ISO/Permenkes/ketentuan teknis lainnya) c. Pengujian dilakukan di laboratorium yang memiliki kompetensi dan/atau terakreditasi d. Seluruh peralatan pengujian harus laik pakai dan terkalibrasi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 541236);
