INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62441788', 62441788, 'analyze_legacy', 'Kab. Blitar', 'kabkota', 'Dinas Komunikasi, Informatika, Statistik dan Persandian', 'Belanja Pemeliharaan Komputer-Komputer Unit-Komputer Jaringan ( Managed service sewa perangkat keamanan (firewall) )', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Blitar (Kab.)', 222444000, 'December 2025', 'APBD', 0, 1, '12 bulan', 'Pengadaan Jasa Managed Service Sewa Perangkat Keamanan (Firewall) selama 12 bulan', 'Spesifikasi Mutu/Kualitas : Scope Of Works (SOW): 1. Perangkat dan Layanan Keamanan a. Next Generation Firewall (NGFW) dengan spesifikasi berikut: • Mampu menangani bandwidth internet 1.6 Gbps • Mampu menangani size user sejumlah minimal 11.000 (11K jumlah pegawai aktif) • Throughput minimal NGFW: 5 Gbps • Interface - 10 Gbe (minimal 3 port) - Selain itu 1 Gbe • Fitur keamanan: - Network Protection (IPS, IDS) - Web & Application Protection (WAF) - Zero days protection - Email Protection (Anti-spam, Antivirus, DLP) - Active Threat Response (mendukung integrasi dengan third party threat feeds) • Mendukung fitur IPSEC dan SSL VPN • Full licensed b. Layanan Keamanan Tambahan (additional security layer): • 1 unit DNS Security • Active Threat Response database c. Lisensi Sertifikat SSL/TLS (Secure Socket Layer) Wildcard untuk subdomain blitarkab.go.id (unlimited) yang berlaku selama 1 (satu) tahun. 2. Implementasi dan Konfigurasi a. Pemasangan, perakitan, dan instalasi unit Firewall dan layanan keamanan tambahan b. Konfigurasi Firewall dan layanan keamanan tambahan beserta fitur-fitur keamanannya c. Wiring dan Cabling system sesuai standar d. Testing dan Commisioning e. Private training bagi tim teknis Diskominfotiksan f. Dokumentasi teknis 3. Managed Service (Full Support) a. Dukungan teknis On-site atau Remote selama masa kontrak b. Update dan Upgrade versi firmware secara berkala c. Backup konfigurasi rutin d. Layanan Hard reset/Flashing Firewall dan layanan keamanan tambahan jika terjadi kendala sistem e. Konsultasi konfigurasi berkelanjutan f. Dokumentasi dan Laporan Bulanan (meliputi traffics dan bandwidth, ancaman dan insiden siber, Trouble dan penanganan, uptime/avalilability firewall, analisis dan rekomendasi) 4. Service Availability Support 24/7 remote monitoring dengan respon cepat. On-site untuk kendala kritis sesuai dengan SOW Spesifikasi Pelayanan : Pelatihan dan Bantuan Teknis dari Penyedia Barang/Jasa (apabila diperlukan) : Ada Pemeliharaan Aspek pemeliharaan dan perbaikan harus dinyatakan dalam ruang lingkup spesifikasi : Garansi akan diberikan oleh penyedia terhadap kerusakan yang tidak diakibatkan oleh kelalaian pengguna, bencana alam, atau modifikasi yang tidak diizinkan Informasi lainnya terkait spesifikasi pelayanan (jika ada) : Harga sudah termasuk pajak, biaya pengiriman, biaya setup, biaya pelatihan dan garansi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 541344);
