INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63080166', 63080166, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERKERETAAPIAN', 'Pengembangan Modul Layanan Bidang Pengawasan LLAKA', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 1500000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 paket', 'Maksud dari Pengembangan Modul Layanan Bidang Pengawasan Lalu Lintas Angkutan Kereta Api untuk menyediakan sistem digital yang mendukung tugas pengawasan lalu lintas angkutan kereta api secara lebih efisien, transparan, dan terintegrasi. Modul ini menjadi alat bantu dalam mewujudkan pengawasan yang berbasis data dan teknologi informasi, sesuai dengan arah transformasi digital sektor transportasi', 'Pengembangan Modul Layanan Bidang Pengawasan Lalu Lintas Angkutan Kereta Api meliputi : 1.Perubahan arsitektur sistem/modul layanan dengan menggunakan teknologi microservices atau arsitektur berorientasi layanan termasuk penyesuaian teknologi standar dengan Portal Layanan dan Data Direktorat Jenderal Perkeretaapian; 2.Optimalisasi penerapan integrasi Single Sign On (SSO) dan Sistem Penghubung Layanan Transportasi (SPLT) HUBNET Kementerian Perhubungan pada Modul Layanan Bidang Pengawasan Lalu Lintas Angkutan Kereta Api untuk mendukung persetujuan terpusat dan data warehouse termasuk integrasi sistem dengan eksternal Direktorat Jenderal Perkeretaapian; 3.Melakukan penyesuaian tampilan User Interface (UI) dan User Experience (UX) agar selaras dengan desain dan standar Portal Layanan Direktorat Jenderal Perkeretaapian; 4.Penyeragaman teknologi database sesuai dengan standar Portal Layanan Direktorat Jenderal Perkeretaapian, serta melakukan peningkatan performa database melalui penyederhanaan relasi dan optimasi struktur; 5.Mengidentifikasi kebutuhan informasi dan proses pengawasan lalu lintas angkutan kereta api; 6.Penambahan/peningkatan fitur layanan diantaranya : a.Fitur layanan monitoring dan pemantauan Standar Pelayanan Minimum (SPM) untuk mendukung evaluasi penetapan jenis, kelas dan kegiatan di stasiun kereta api; b.Fitur untuk penyelenggaraan angkutan mudik motor gratis; c.Fitur Pengawasan Sistem dan Prosedur Pengoperasian Kereta Api; d.Fitur pengawasan Penetapan atau Persetujuan Trase Jalur Kereta Api; e.Fitur Pengawasan Penyelenggaraan Angkutan dan Lalu Lintas Kereta Api. 7.Melakukan preventif maintenance pada modul layanan; 8.Melakukan technical support kepada user aplikasi; 9.Peningkatan keamanan dan kinerja Modul Layanan Bidang Pengawasan Lalu Lintas dan Angkutan Kereta Api termasuk melakukan uji keamanan/pentest dan update modul layanan. 10.Workshop/pelatihan untuk penggunaan dan pengolahan Modul Layanan Bidang Pengawasan Lalu Lintas Angkutan Kereta Api.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 547284);
