INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62446014', 62446014, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan Vaksin Hepatitis B0 Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 113645627000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 PT', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda dengan Menyediakan Vaksin Hepatitis B0 Tahun 2026 Tahap I sebanyak 1.984.210 vial dengan estimasi harga satuan Rp57.275', 'Spesifikasi Vaksin Hepatitis sebagai berikut : 1. Vaksin Hepatitis B (Versi 1) : Nama : Vaksin Hepatitis B rekombinan; Komposisi : Setiap dosis (0,5 ml) mengandung 10,0 mcg HbsAg teradsorbsi pada 0,25 mg alumunium hidroksida; Indikasi vaksin : Mencegah penyakit Hepatitis B pada bayi baru lahir; Kemasan : Dikemas dalam single dose Jika kemasan single dose maka setiap kemasan dilengkapi dengan dilengkapi jarum ukuran 25 G x 5/8”, Dalam setiap kemasan ampul/vial/pouch dilengkapi dengan indikator Vaccine Vial Monitor (VVM), Dilengkapi dengan nomor batch, masa kadaluarsa, dan brosur/leaflet yang berisi petunjuk pemakaian, indikasi, kontra indikasi, dan petunjuk penggunaan VVM dalam Bahasa Indonesia; Masa Kadaluarsa : Saat diterima di pusat/ provinsi minimal 14 bulan; Izin Vaksin : Telah teregistrasi oleh Badan Pengawas Obat dan Makanan (BPOM); Persyaratan rilis dan pendistribusian vaksin : Vaksin telah mendapatkan Persetujuan lot release dalam bentuk sertifikat Certificate of Release (CoR) dari BPOM sebelum di distribusikan Dilengkapi dengan Vaccine Arrival Report (VAR) danDilengkapi dengan Vaccine Arrival Report (VAR)dan alat pemantau suhu secara kontinyu / data Logger; 2. Vaksin Hepatitis B (Versi 2) : Nama : Vaksin Hepatitis B. Komposisi : Vaksin Setiap dosis (0,5 mL) mengandung: - 10µg Hepatitis B Surface Antigen - Natrium klorida 4,5mg - Aluminium kalium sulfat dodekahidrat 1.52mg - Natrium hidroksida 0,385mg. Indikasi Vaksin : Pencegahan infeksi Hepatitis B pada bayi baru lahir dan bayi dibawah usia 1 tahun, terutama pada bayi dengan HBsAg reaktif dan/atau bayi dengan ibu yang positif Hepatitis B. Kemasan : Suspensi injeksi Dus, 1 Pre-Filled Syringe (PFS) @10 µg/0,5mL (1 dosis), Dalam setiap kemasan ampul/vial/pouch dilengkapi dengan indikator paparan suhu panas dan/atau Vaccine Vial Monitor (VVM), Dilengkapi dengan nomor batch, masa kadaluarsa, dan brosur/leaflet yang berisi petunjuk pemakaian, indikasi, kontra indikasi dalam Bahasa Indonesia, Masa Kadaluarsa : Saat diterima di pusat/ provinsi minimal 14 bulan. Izin Vaksin : Telah teregistrasi oleh Badan Pengawas Obat dan Makanan (BPOM). Persyaratan rilis dan pendistribusian vaksin : Vaksin telah mendapatkan persetujuan lot release dalam bentuk sertifikat Certificate of Release (CoR) dari BPOM sebelum didistribusikan, Dilengkapi dengan Vaccine Arrival Report (VAR) dan alat pemantau suhu secara kontinyu / data Logger', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 548327);
