INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62446037', 62446037, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan Vaksin DPT-Hb-Hib Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 185467500000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '1 PT', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda dengan Menyediakan Vaksin DPT-Hb-Hib Tahun 2026 Tahap I sebanyak 741.870 vial dengan estimasi harga satuan Rp250.000', 'Spesifikasi Vaksin DPT-Hb-Hib sebagai berikut : A. Vaksin DPT-Hb-Hib (Versi 1) : 1. Nama DPT-HB-Hib Pentavalent, 2. Komposisi Vaksin Setiap dosis DPT-HB-Hib mengandung: - Diphteria Toxoid NMT 25 lf, - Tetanus Toxoid 2,5 lf, - Hepatitis B Surface Antigen NLT 10 mcg, - Haemophilus Influenzae Type B, - Polysaccharide Conjugated to Tetanus Toxoid 10 mcg, - Inactivated Bordetella Pertussis NMT 10 ou. 3. Indikasi Vaksin Mencegah penyakit Difteri, Pertusis, Tetanus, Hepatitis B, Haemophilus influenzae tipe b. 4. Kemasan : Dikemas dalam multi dose, Dalam setiap kemasan ampul/vial/pouch dilengkapi dengan indikator paparan suhu panas dan/atau Vaccine Vial Monitor (VVM), Dilengkapi dengan nomor batch, masa kadaluarsa, dan brosur/leaflet yang berisi petunjuk pemakaian, indikasi, kontra indikasi, dan petunjuk penggunaan VVM dalam Bahasa Indonesia. 5. Masa Kadaluarsa Masa kadaluarsa vaksin saat diterima di pusat/provinsi minimal 14 bulan, 6. Izin Vaksin Telah teregistrasi oleh Badan Pengawas Obat dan Makanan (BPOM), 7. Persyaratan rilis dan pendistribusian vaksin :  Vaksin telah mendapatkan persetujuan lot release dalam bentuk sertifikat Certificate of Release (CoR) dari BPOM sebelum di distribusikan,  Dilengkapi dengan Vaccine Arrival Report (VAR) dan alat pemantau suhu secara kontinyu / data Logger. B. Vaksin DPT-Hb-Hib (Versi 2) : 1. Nama DPT-HB-Hib Pentavalent, 2. Komposisi Vaksin Setiap dosis DPT-HB-Hib mengandung: - Diphteria Toxoid NMT 20 lf - Tetanus Toxoid 7,5 lf - Hepatitis B Surface Antigen NLT 10 mcg - Haemophilus Influenzae Type B - Polysaccharide Conjugated to Tetanus Toxoid 10 mcg, - Inactivated Bordetella Pertussis NMT 12 ou 3. Indikasi Vaksin Mencegah penyakit Difteri, Pertusis, Tetanus, Hepatitis B, Haemophilus influenzae tipe b 4. Kemasan : Dikemas dalam multi dose, Dalam setiap kemasan ampul/vial/pouch dilengkapi dengan indikator paparan suhu panas dan/atau Vaccine Vial Monitor (VVM), Dilengkapi dengan nomor batch, masa kadaluarsa, dan brosur/leaflet yang berisi petunjuk pemakaian, indikasi, kontra indikasi, dan petunjuk penggunaan VVM dalam Bahasa Indonesia. 5. Masa Kadaluarsa Masa kadaluarsa vaksin saat diterima di pusat/provinsi minimal 14 bulan, 6. Izin Vaksin Telah teregistrasi oleh Badan Pengawas Obat dan Makanan (BPOM), 7. Persyaratan rilis dan pendistribusian vaksin :  Vaksin telah mendapatkan persetujuan lot release dalam bentuk sertifikat Certificate of Release (CoR) dari BPOM sebelum di distribusikan,  Dilengkapi dengan Vaccine Arrival Report (VAR) dan alat pemantau suhu secara kontinyu / data Logger. C. Vaksin DPT-Hb-Hib (Versi 3) : 1. Nama DPT-HB-Hib Pentavalent, 2. Komposisi Vaksin Setiap dosis DPT-HB-Hib mengandung: - Dipteria Toxoid : 25 lf (≥ 30 IU), - Tetanus toxoid : 5,5 lf ((≥ 60 IU), - Bakteri Pertusis (Whole cell) : 16 IOU (≥ 4 IU) r-HB Ag: 12,5 μg, - Purified capsular polusacharida of Hib (PRP) covalenty linked to 20 to 36,7 μg of tetanus toxoid : 11 μg, - Al++ (as AlPO4) : ≤ 1,25 mg, - Thimerosal :0,01 % w/v, 3. Indikasi Vaksin Mencegah penyakit Difteri, Pertusis, Tetanus, Hepatitis B, Haemophilus influenzae tipe b, 4. Kemasan  Dikemas dalam multi dose, Dalam setiap kemasan ampul/vial/pouch dilengkapi dengan indikator paparan suhu panas dan/atau Vaccine Vial Monitor (VVM), Dilengkapi dengan nomor batch, masa kadaluarsa, dan brosur/leaflet yang berisi petunjuk pemakaian, indikasi, kontra indikasi, dan petunjuk penggunaan VVM dalam Bahasa Indonesia, 5. Masa Kadaluarsa Masa kadaluarsa vaksin saat diterima di pusat/provinsi minimal 14 bulan, 6. Izin Vaksin Telah teregistrasi oleh Badan Pengawas Obat dan Makanan (BPOM), 7. Persyaratan rilis dan pendistribusian vaksin :  Vaksin telah mendapatkan persetujuan lot release dalam bentuk sertifikat Certificate of Release (CoR) dari BPOM sebelum di distribusikan,  Dilengkapi dengan Vaccine Arrival Report (VAR) dan alat pemantau suhu secara kontinyu / data Logger', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 548570);
