INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65825192', 65825192, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'KANTOR PERTANAHAN KAB GORONTALO', 'Biaya Satpam', 'Jasa Lainnya', 'E-Purchasing', 'Gorontalo, Gorontalo (Kab.)', 83182000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '22 OB @3781000', 'Tugas dan Fungsi Utama Memelihara Keamanan: Melakukan patroli, penjagaan, pengawalan (Turjawali), serta mengendalikan akses masuk. Memberikan Rasa Aman: Memberikan pelayanan dan perlindungan bagi karyawan, tamu, pengunjung, dan masyarakat di area kerjanya. Mencegah Kejahatan: Melindungi aset dan mencegah aktivitas mencurigakan atau kejahatan melalui pengawasan dan visibilitas tinggi. Penanggulangan Insiden: Menangani insiden atau kecelakaan awal sebelum bantuan profesional datang.', 'Satpam (Satuan Pengamanan) adalah profesi petugas keamanan swakarsa yang bermitra dengan Polri, bertugas menjaga keamanan, ketertiban, dan keselamatan di lingkungan kerjanya (perusahaan, perumahan, dll.) melalui patroli, pengawasan, dan pelayanan untuk menciptakan rasa aman, dengan jenjang karier berbasis sertifikasi Gada (Gada Pratama, Madya, Utama) yang diakui secara hukum dan diatur oleh Peraturan Kepolisian.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 549147);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62517273', 62517273, 'analyze_legacy', 'Kota Tangerang Selatan', 'kabkota', 'DINAS PERHUBUNGAN', 'Belanja Sewa Kendaraan Bermotor Penumpang  Operasional Angkutan Sekolah', 'Jasa Lainnya', 'E-Purchasing', 'Banten, Tangerang Selatan (Kota) | Banten, Tangerang Selatan (Kota)', 3064967400, 'December 2025', 'APBD', 1, 1, '2 Paket', 'Layanan Operasional Bus Sedang 102.300 KM / Tahun Layanan Operasional Micro Bus 25.300 KM / Tahun', 'Pajak Kendaraan berdomisili di WilProvinsi Banten; Kendaraan maksimal berumur 5 tahun;Kendaraan berwarna kuning dan dilengkapi tulisan ”BUS SEKOLAH”;Kapasitas Penumpang untuk bus sedang minimal 28 tempat duduk dan 18 berdiri; Kapasitas Micro Bus 19;Kompentesi Pengemudi dilengkapan dengan SIM B1 dan BPJS ;Bersedia menyediakan Pengemudi dan Kondektur;Fitur Keamanan dan Keselamatan dilengakapi dengan GPS, CCTV dan yang terkoneksi dengan SIOPTIMUS;Dilengkapi dengan Tabung APAR, Alat Pemecah Kaca, Kelengkapan P3K dan Kotak Sampah;Dilengkapi dengan tempat duduk disabilitas dan Informasi Running Text;Kesanggupan memenuhi (SPM) yang di tentukan; Harga tertera sudah termasuk : biaya investasi kendaraan, gaji awak kendaraan beserta THR, BBM, asuransi kendaraan, BPJS awak kendaraan, pengelolaan operasional, perbaikan komponen kendaraan dan perawatan kendaraan, retribusi, gaji pegawai kantor beserta THR, overhead, pajak kendaraan dan pajak Perusahaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 549148);
