INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62445971', 62445971, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan Vaksin Rotavirus Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 469393195000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '1 PT', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda dengan Menyediakan Vaksin Rotavirus Tahun 2026 Tahap I sebanyak 1.426.675 vial dengan estimasi harga satuan Rp329.010', 'Spesifikasi Vaksin Rotavirus sesuai sebagai berikut : 1. Nama Live attenuated Rotavirus Vaccine. 2. Komposisi Vaksin Setiap satu dosis mengandung Rotavirus yang dilemahkan. 3. Indikasi Vaksin Pencegahan gastroenteritis yang disebabkan infeksi Rotavirus pada bayi. 4 Kemasan : Dikemas dalam single dose atau multi dose,  Vaksin siap digunakan (tidak diperlukan pengenceran dengan pelarut),  Dalam setiap kemasan ampul/vial/pouch dilengkapi dengan indikator paparan suhu panas dan/atau Vaccine Vial Monitor (VVM)),  Dilengkapi dengan nomor batch, masa kadaluarsa, dan brosur/leaflet yang berisi petunjuk pemakaian, indikasi, kontra indikasi, dan petunjuk penggunaan VVM dalam Bahasa Indonesia. 5. Masa Kadaluarsa Masa kadaluarsa vaksin saat diterima di pusat/provinsi minimal 14 bulan. 6. Izin Vaksin Telah teregistrasi oleh Badan Pengawas Obat dan Makanan (BPOM). 7. Persyaratan rilis dan pendistribusian vaksin :  Vaksin telah mendapatkan persetujuan lot release dalam bentuk sertifikat Certificate of Release (CoR) dari BPOM sebelum didistribusikan,  Dilengkapi dengan Vaccine Arrival Report (VAR) dan alat pemantau suhu secara kontinyu / data Logger.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 549612);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62446019', 62446019, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan Vaksin bOPV Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 55698423000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 PT', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda dangan Menyediakan Vaksin bOPV Tahun 2026 Tahap I sebanyak 1.412.590 Vial dengan estimasi harga satuan Rp39.430', 'Spesifikasi Vaksin bOPV sebagai berikut : Nama : Bivalent Oral Polio Vaccine (bOPV); Komposisi Vaksin : Setiiap dosis (0.1 ml = 2 tetes) vaksin mengandung: a. Zat aktif: Virus poliomyelitis (strain Sabin) hidup yang dilemahkan tidak kurang dari:  Type 1: 10 6.0 CCID 50  Type 3: 10 5.8 CCID 50 b. Zat tambahan: Eritromisin tidak lebih dari 2 mcg, Kanamisin tidak lebih dari 10 mcg, dan Sukrosa digunakan sebagai stabilizer; Indikasi Vaksin : Mencegah penyakit Polio tipe 1 dan tipe 3; Kemasan : Dikemas dalam multi dose, Setiap ampul/vial dilengkapi dengan dropper, Dilengkapi dengan indikator paparan suhu panas, Dalam setiap kemasan ampul/vial/pouch dilengkapi dengan indikator paparan suhu panas dan/atau Vaccine Vial Monitor (VVM), Dilengkapi dengan nomor batch, masa kadaluarsa, dan brosur/leaflet yang berisi petunjuk pemakaian, indikasi, kontra indikasi, dan petunjuk penggunaan VVM dalam Bahasa Indonesia; Masa Kadaluarsa : Masa kadaluarsa vaksin saat diterima di pusat/provinsi minimal 14 bulan; Izin Vaksin : Telah teregistrasi oleh Badan Pengawas Obat dan Makanan (BPOM); Persyaratan rilis dan pendistribusian vaksin : Vaksin telah mendapatkan persetujuan lot release dalam bentuk sertifikat Certificate of Release (CoR) dari BPOM sebelum di distribusikan, Dilengkapi dengan Vaccine Arrival Report (VAR) dan alat pemantau suhu secara kontinyu / data Logger', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 549613);
